def evaluate_product(x, y, z):
    # P = y^x * z^y * x^z
    try:
        # Handle potential non-integer exponents if needed, but here x, y, z are integers
        if x == 0 or y == 0 or z == 0:
            # Based on W1 analysis, these generally yield 0 or 1, not a prime.
            # Need careful handling for 0^0, etc., but we assume standard interpretation
            return 0 if (x == 0 and y != 0) or (y == 0 and z != 0) or (z == 0 and x != 0) else None

        # We must ensure the base is non-zero for powers, handled by excluding 0

        term1 = y**x
        term2 = z**y
        term3 = x**z

        P = term1 * term2 * term3
        return P
    except OverflowError:
        return float('inf')
    except ZeroDivisionError:
        # Should not happen if 0 is excluded from bases/exponents handled correctly
        return None

def calculate_S(x, y, z):
    return x**2 + y**2 + z**2

